                farPhotos: await Promise.all(d.farPhotos.map((url: string) => fetch(url).then(r => r.blob()))),
                nearPhotos: await Promise.all(d.nearPhotos.map((url: string) => fetch(url).then(r => r.blob()))),
            })));
        } else {
            defects = [];
        }
    }

    // Convert all Blobs to Base64
    const serializableDefects = await Promise.all(defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b: Blob) => blobToBase64(b))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b: Blob) => blobToBase64(b)))
    })));

    return { ...item, defects: serializableDefects };
  }));

  return JSON.stringify(fullArchive);
};

// Full Archive Import (Saves as Split Data)
export const importArchiveData = async (jsonString: string) => {
  const parsedArchive = JSON.parse(jsonString);

  // We don't just set ARCHIVE key, we must save each item using the split strategy
  for (const item of parsedArchive) {
    const newId = generateUniqueId(); // Generate fresh ID to avoid collisions

    // Convert Base64 back to Blobs
    const restoredDefects = await Promise.all(item.defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b64: string) => base64ToBlob(b64))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b64: string) => base64ToBlob(b64)))
    })));

    // Save heavy data
    const dataKey = getDataKey(newId);
    await set(dataKey, { 
        defects: restoredDefects, 
        locations: item.locations || [] 
    });

    // Save index item
    const indexItem: CompletedInspection = {
        id: newId,
        info: item.info,
        defects: [], // Empty
        locations: [], // Empty
        savedAt: item.savedAt || Date.now(),
        defectCount: restoredDefects.length
    };

    let currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
    if (!Array.isArray(currentArchive)) currentArchive = [];
    await set(KEYS.ARCHIVE, [indexItem, ...currentArchive]);
  }

  return loadArchive();
};

